-- Schema of v1.0.0, previously generated by Hibernate (ddl-auto: update).
-- Existing databases created by that version are baselined at V1 (see README).

-- Hibernate default sequences: one per entity, named after its table, allocationSize 50
create sequence categories_seq start with 1 increment by 50;
create sequence products_seq start with 1 increment by 50;
create sequence customers_seq start with 1 increment by 50;
create sequence carts_seq start with 1 increment by 50;
create sequence cart_items_seq start with 1 increment by 50;
create sequence orders_seq start with 1 increment by 50;
create sequence order_items_seq start with 1 increment by 50;

create table categories (
    id   bigint       not null,
    name varchar(100) not null,
    constraint pk_categories primary key (id),
    constraint uk_categories_name unique (name)
);

create table products (
    id          bigint         not null,
    name        varchar(150)   not null,
    description varchar(2000),
    price       numeric(10, 2) not null,
    stock       integer        not null,
    category_id bigint         not null,
    version     bigint,
    constraint pk_products primary key (id),
    constraint fk_products_category foreign key (category_id) references categories (id)
);
create index idx_products_category_id on products (category_id);

create table customers (
    id        bigint       not null,
    email     varchar(255) not null,
    full_name varchar(100) not null,
    constraint pk_customers primary key (id),
    constraint uk_customers_email unique (email)
);

create table carts (
    id          bigint not null,
    customer_id bigint not null,
    constraint pk_carts primary key (id),
    constraint uk_carts_customer_id unique (customer_id),
    constraint fk_carts_customer foreign key (customer_id) references customers (id)
);

create table cart_items (
    id         bigint  not null,
    cart_id    bigint  not null,
    product_id bigint  not null,
    quantity   integer not null,
    constraint pk_cart_items primary key (id),
    constraint uk_cart_items_cart_product unique (cart_id, product_id),
    constraint fk_cart_items_cart foreign key (cart_id) references carts (id),
    constraint fk_cart_items_product foreign key (product_id) references products (id)
);
create index idx_cart_items_product_id on cart_items (product_id);

create table orders (
    id           bigint                   not null,
    customer_id  bigint                   not null,
    status       varchar(20)              not null,
    total_amount numeric(12, 2)           not null,
    created_at   timestamp(6) with time zone not null,
    version      bigint,
    constraint pk_orders primary key (id),
    constraint ck_orders_status check (status in ('PENDING', 'CONFIRMED')),
    constraint fk_orders_customer foreign key (customer_id) references customers (id)
);
create index idx_orders_customer_id on orders (customer_id);

create table order_items (
    id           bigint         not null,
    order_id     bigint         not null,
    product_id   bigint         not null,
    product_name varchar(150)   not null,
    unit_price   numeric(10, 2) not null,
    quantity     integer        not null,
    constraint pk_order_items primary key (id),
    constraint fk_order_items_order foreign key (order_id) references orders (id),
    constraint fk_order_items_product foreign key (product_id) references products (id)
);
create index idx_order_items_order_id on order_items (order_id);
create index idx_order_items_product_id on order_items (product_id);
